const problems = [{"value": "polynomial", "label": "Polynôme"}, {"value": "exponential", "label": "Exponentielle"}, {"value": "oscillatory", "label": "Oscillation"}, {"value": "local_curvature", "label": "Pic local"}, {"value": "discontinuous", "label": "Discontinuité"}, {"value": "rare_tail", "label": "Événement rare"}, {"value": "european", "label": "Option européenne"}, {"value": "asian_nested", "label": "Option asiatique conditionnelle"}, {"value": "interaction_2d", "label": "Interactions · 2 dimensions"}, {"value": "interaction_5d", "label": "Interactions · 5 dimensions"}, {"value": "interaction_10d", "label": "Interactions · 10 dimensions"}, {"value": "interaction_20d", "label": "Interactions · 20 dimensions"}];

const budgets = [
  {value: "128", label: "128 appels"},
  {value: "512", label: "512 appels"},
  {value: "2048", label: "2 048 appels"},
];
const format = new Intl.NumberFormat("fr-FR", { maximumSignificantDigits: 4 });
function display(value: number) {
  if (value === 0) return "0";
  if (Math.abs(value) < .0001) return value.toExponential(3).replace(".", ",");
  return format.format(value);
}

export default function ExpectationBenchmark() {
  const theme = useHostTheme();
  const [model, setModel] = useState("asian_nested");
  const [budget, setBudget] = useState("128");
  const [sortBy, setSortBy] = useState("rmse");
  const index = sortBy === "cpu" ? 5 : 2;
  const rows = [...data[model + ":" + budget]]
    .sort((left, right) => left[index] - right[index])
    .map(([method, calls, rmse, bias, variance, cpu, memory]) =>
      [method, format.format(calls), display(rmse), display(bias), display(variance), display(cpu), display(memory)]);

  return (
    <Stack gap={20} style={{ maxWidth: 1050, margin: "0 auto", padding: 24 }}>
      <Stack gap={8}>
        <H1>Estimation d’espérances à budget exact limité</H1>
        <p style={{ color: theme.accent.primary, fontSize: 16, margin: 0 }}>
          Aucun gain reproductible avec moins d’appels face à la meilleure référence testée.
        </p>
        <Text>
          Sur l’option asiatique, à un budget de 128 appels, le surrogate réduit la RMSE du
          Monte Carlo de 0,0136 à 0,000388. Gauss–Hermite atteint 7,44 × 10⁻⁷ en 121 appels.
        </Text>
      </Stack>
      <Stack gap={8}>
        <H2>Résultats par intégrand et budget</H2>
        <Row gap={12} style={{ flexWrap: "wrap" }}>
          <label>Intégrand <Select value={model} onChange={setModel} options={problems} /></label>
          <label>Budget <Select value={budget} onChange={setBudget} options={budgets} /></label>
          <label>Tri <Select value={sortBy} onChange={setSortBy} options={[
            { value: "rmse", label: "RMSE" }, { value: "cpu", label: "Temps CPU" },
          ]} /></label>
        </Row>
        <Table striped headers={["Méthode","Appels exacts","RMSE","Biais","Variance","CPU médian (ms)","Pic suivi (Mio)"]}
          rows={rows} columnAlign={["left","right","right","right","right","right","right"]} />
        <small style={{ color: theme.text.secondary }}>
          Campagne synthétique · 32 graines par configuration · RMSE et biais en unités de l’intégrale
        </small>
      </Stack>
      <Stack gap={8}>
        <H2>Transfert aux pics inédits</H2>
        <Text>
          La spline à 64 appels donne des erreurs entre 6,67 × 10⁻⁹ et 5,34 × 10⁻³.
          Les neuf cas sont battus en précision par une quadrature plafonnée à 256 appels.
        </Text>
      </Stack>
    </Stack>
  );
}
